import {STORAGE_KEY,TYPES,CHAPTER_TITLES,emptyState,sanitizeState,checkShort,shuffle,recordAttempt,selectExam,examScore,questionPoints,conceptProgress,questionRevision,acknowledgeRevision,emptyWorksheetDraft,worksheetHasAnswer,evaluateWorksheet} from './study.js?v=20261019-r7';

const $=s=>document.querySelector(s);
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',bank:'M4 5h16v15H4z M8 2v6 M16 2v6 M8 12h8 M8 16h5',exam:'M8 4H5v17h14V4h-3 M8 2h8v5H8z M8 12h8 M8 16h5',wrong:'M5 3h14v18l-7-4-7 4z M9 7l6 6 M15 7l-6 6',cards:'M5 3h15v15H5z M2 7v14h14 M9 8h7 M9 12h5',chart:'M4 3v18h17 M8 16v-5 M13 16V7 M18 16V4',source:'M6 2h8l5 5v15H6z M14 2v6h5 M9 12h7 M9 16h7',gear:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M4 12h15 M13 6l6 6-6 6',back:'M20 12H5 M11 6l-6 6 6 6',check:'m5 12 4 4L19 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',bookmark:'M6 3h12v18l-6-4-6 4z',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',menu:'M4 6h16 M4 12h16 M4 18h16',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',refresh:'M20 8a8 8 0 1 0 0 9 M20 3v6h-6',shield:'M12 2 21 6v6c0 6-9 10-9 10S3 18 3 12V6z M8 11l3 3 5-6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',print:'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 13h12v8H6z',close:'M5 5l14 14 M19 5 5 19'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const btn=(text,action,extra='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,href,cls='')=>`<a class="btn ${cls}" href="#/${href}">${text}</a>`;
const title=(eyebrow,name,copy,action='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${name}</h1>${copy?`<p>${copy}</p>`:''}</div>${action}</div>`;
const empty=(name,copy,action='')=>`<div class="surface empty">${icon('book')}<h3>${name}</h3><p>${copy}</p>${action}</div>`;
const opts=(list,value)=>list.map(([v,t])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(t)}</option>`).join('');
const notice=(text,warm=false)=>`<div class="notice ${warm?'warm':''}">${text}</div>`;
let data,concepts,questions,byId,byConcept,state,patterns,reviewData,cramData;
let route='bank',routeId='',params=new URLSearchParams(),mobile=false;
let filters={query:'',chapter:'all',type:'all',difficulty:'all',status:'all',concept:'all'};
let reviewTab='wrong';
let bankMode='course',page=0,practiceQueue=[],practice={choice:null,text:'',revealed:false,graded:false,score:0,rubric:[]};
let examMode='mixed',examChapter='all',examMinutes='50';
let flash={chapter:'all',index:0,flipped:false,ids:[]};
let storageFailed=false;

function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{if(!storageFailed){storageFailed=true;toast('브라우저 저장 공간이 부족합니다. 기록을 백업해 주세요.');}}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function wrong(){return questions.filter(q=>state.attempts[q.id]&&!state.attempts[q.id].correct);}
function learnedPercent(){return Math.round(state.learned.length/concepts.length*100);}
function stats(){const a=Object.values(state.attempts).filter(a=>!a.needsReview);return {seen:a.length,correct:a.filter(x=>x.correct).length,rate:a.length?Math.round(a.reduce((sum,x)=>sum+x.score,0)/a.length*100):0};}
function setQueue(qs){practiceQueue=[...new Set(qs.map(q=>typeof q==='string'?q:q.id))];try{sessionStorage.setItem('security-practice-queue',JSON.stringify(practiceQueue));}catch{}}
function routeTo(hash){location.hash='#/'+hash;}
function goPractice(id,queue){if(queue)setQueue(queue);routeTo('worksheet/selection?question='+id);}
function resetPractice(){practice={choice:null,text:'',revealed:false,graded:false,score:0,rubric:[]};}
function readRoute(){
  const previous=route+'/'+routeId;const [path,query='']=(location.hash.slice(2)||'bank').split('?');
  [route,routeId='']=path.split('/');params=new URLSearchParams(query);
  const allowed=['dashboard','bank','cram','concepts','concept','chapter','worksheet','practice','exam','wrong','cards','stats','sources','settings'];if(!allowed.includes(route))route='bank';
  if(route==='practice'&&byId.has(routeId)){params.set('question',routeId);routeId=String(byId.get(routeId).chapter);route='worksheet';}
  if(previous!==route+'/'+routeId)resetPractice();
  if(params.has('chapter')){filters.chapter=params.get('chapter');filters.concept='all';page=0;}
  if(params.has('concept')){filters.concept=params.get('concept');filters.chapter='all';bankMode='all';page=0;}
  const allowedStatuses=(route==='concepts'||(route==='bank'&&bankMode==='course'))?['all','unseen','learned']:['all','unseen','wrong','bookmarked'];
  if(!allowedStatuses.includes(filters.status))filters.status='all';
  mobile=false;render();const focusItem=route==='concept'?document.getElementById('concept-'+routeId):route==='worksheet'&&params.has('question')?document.getElementById('worksheet-'+params.get('question')):null;if(focusItem)focusItem.scrollIntoView({block:'start'});else window.scrollTo({top:0,behavior:'instant'});
}
function shell(body){
 const navs=[['dashboard','학습 대시보드','grid'],['bank','문제로 개념 완주','bank'],['cram','벼락치기 핵심','clock'],['concepts','개념 노트','book'],['exam','실전 모의고사','exam'],['wrong','오답 · 북마크','wrong'],['cards','암기 카드','cards'],['stats','취약 개념 분석','chart'],['sources','시험 양식 · 자료 분석','source']];
 const active=['practice','worksheet'].includes(route)?'bank':['concept','chapter'].includes(route)?'concepts':route;
 return `<div class="layout"><aside class="sidebar ${mobile?'open':''}" aria-label="주 메뉴"><button class="mobile-close" data-action="menu" aria-label="탐색 메뉴 닫기">${icon('close')}</button><a class="brand" href="#/dashboard"><img src="./icon.svg" alt=""><span><strong>MIDTERM LAB</strong><small>COMPUTER SECURITY</small></span></a><div class="sidebar-label">MY STUDY SPACE</div><nav class="nav">${navs.map(([id,name,ic])=>`<a href="#/${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}${name}${id==='wrong'?`<span class="count">${wrong().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-progress"><div class="spread small"><span>개념 학습</span><span>${learnedPercent()}%</span></div><div class="progress"><i style="width:${learnedPercent()}%"></i></div><div style="font-size:10px;color:#88aaa4">${state.learned.length} / ${concepts.length}개 개념 확인 완료</div></div><div class="spread"><button data-action="theme">${icon(state.theme==='dark'?'sun':'moon')} ${state.theme==='dark'?'라이트 모드':'다크 모드'}</button><a href="#/settings" aria-label="기록 관리 설정" style="color:#adc0bd;padding:8px">${icon('gear')}</a></div></div></aside><button class="scrim" data-action="menu" aria-label="메뉴 닫기"></button><div class="shell"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="메뉴 ${mobile?'닫기':'열기'}" aria-expanded="${mobile}">${icon(mobile?'close':'menu')}</button><div class="crumb"><span>2026 · 2학기</span><span>/</span><b>컴퓨터보안 중간고사</b></div><div class="top-end"><div class="top-tag"><i class="live-dot"></i> PERSONAL STUDY ROOM</div><div class="avatar" aria-label="개인 학습실">CS</div></div></header>${state.exam?.status==='active'&&route!=='exam'?`<div class="exam-banner">진행 중인 모의고사가 있습니다. <a href="#/exam">시험 이어 풀기 →</a> · 남은 시간은 계속 흐릅니다.</div>`:''}<main id="main" class="main" tabindex="-1">${body}<footer class="footer"><span>수업자료 4개 · ${data.reduce((s,c)=>s+c.slideCount,0)}슬라이드 기반 자체 제작 학습 자료</span><span class="foot-code">READ → RECALL → EXPLAIN → REVIEW</span></footer></main></div></div>`;
}
function render(){
 const focused=document.activeElement,id=focused?.id,selection=focused?.selectionStart;
 document.documentElement.dataset.theme=state.theme;
 let body='';
 if(route==='bank')body=bankPage();else if(route==='cram')body=cramPage();else if(route==='concepts')body=conceptsPage();else if(route==='concept')body=conceptPage();else if(route==='chapter')body=chapterPage();else if(route==='worksheet')body=worksheetPage();else if(route==='practice')body=practicePage();else if(route==='dashboard')body=dashboardPage();else if(route==='exam')body=examPage();else if(route==='wrong')body=wrongPage();else if(route==='cards')body=cardsPage();else if(route==='stats')body=statsPage();else if(route==='sources')body=sourcesPage();else body=settingsPage();
 $('#app').innerHTML=shell(body);
 document.title=`${({bank:'문제은행',cram:'벼락치기 핵심',concepts:'개념 노트',concept:'장별 개념 학습',chapter:'장별 개념 학습',practice:'문제 풀이',worksheet:'스크롤 문제 풀이',dashboard:'학습 대시보드',exam:'실전 모의고사',wrong:'오답노트',cards:'암기 카드',stats:'취약 개념 분석',sources:'자료 분석',settings:'기록 관리'})[route]} · 컴퓨터보안 LAB`;
 if(id&&document.getElementById(id)){const f=document.getElementById(id);f.focus({preventScroll:true});if(typeof selection==='number'&&f.setSelectionRange)try{f.setSelectionRange(selection,selection);}catch{}}
 tick();
}
function statCards(){const s=stats();return `<div class="stats-grid">${[['bank','문제은행',questions.length,'문항','4지선다 · OX · 단답 · 서술'],['book','개념 노트',concepts.length,'개념','정의·원리·예시·핵심 구분'],['check','지금까지 푼 문제',s.seen,'문항',`최근 답안 기준 · ${s.correct}개 완전 정답`],['chart','최근 답안 득점률',s.rate,'%',s.seen?'서술형 자기평가 점수 포함':'첫 문제를 풀어 학습을 시작하세요']].map(([ic,label,n,unit,foot])=>`<div class="surface stat"><div class="stat-label">${icon(ic)}${label}</div><b class="stat-number">${n}<small>${unit}</small></b><div class="stat-footer">${foot}</div></div>`).join('')}</div>`;}
function hero(){return `<section class="hero"><div><div class="eyebrow">UNDERSTAND IT. THEN EXPLAIN IT.</div><h2>정답을 아는 것에서,<br>설명할 수 있는 실력으로.</h2><p>문제 아래에서 보기의 이유와 관련 개념을 함께 익히세요.<br>키워드의 뜻과 답안 구성 순서를 익힌 뒤, 해설을 접고 내 문장으로 써 보세요.</p><div class="actions">${btn(`이어서 공부하기 ${icon('arrow')}`,'continue')}${link('서술형 모의고사','exam','secondary')}</div><div class="hero-stats"><span><b>04</b> 강의자료</span><span><b>244</b> 슬라이드</span><span><b>13</b> 실전 문항 구성</span></div></div><svg class="hero-visual" viewBox="0 0 160 170" fill="none" aria-hidden="true"><circle cx="80" cy="85" r="65" stroke="#c1d5c3" stroke-dasharray="3 7"/><circle cx="80" cy="85" r="49" stroke="#c1d5c3"/><path d="M80 37 116 52v38c0 23-36 46-36 46s-36-23-36-46V52z" fill="#d8e7d8" stroke="#66947a" stroke-width="1.5"/><path d="m64 84 12 12 23-28" stroke="#52846a" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="M14 64h20 M126 108h20 M80 10v17 M80 147v13" stroke="#9dbba4"/><circle cx="13" cy="64" r="3" fill="#82a68c"/><circle cx="147" cy="108" r="3" fill="#82a68c"/></svg></section>`;}
function chapterCards(){return `<div class="chapter-grid">${data.map(ch=>{const n=questions.filter(q=>q.chapter===ch.chapter).length,c=ch.concepts.length;return `<button class="chapter-card ${filters.chapter===String(ch.chapter)?'selected':''}" data-action="chapter" data-value="${ch.chapter}" aria-pressed="${filters.chapter===String(ch.chapter)}"><small>CHAPTER ${String(ch.chapter).padStart(2,'0')}</small><span class="chapter-num">${String(ch.chapter).padStart(2,'0')}</span><h3>${e(ch.title)}</h3><div class="chapter-meta"><span>개념 <b>${c}</b></span><span>문제 <b>${n}</b></span><span>${ch.slideCount}p</span></div></button>`;}).join('')}</div>`;}
function searchFilters(kind='bank'){
 return `<div class="surface filters"><div class="search-wrap">${icon('search')}<input id="search-query" class="input" aria-label="${kind==='concept'?'개념':'문제'} 검색" placeholder="${kind==='concept'?'개념 이름과 내용 검색':'개념, 문제, 핵심어로 검색'}" value="${e(filters.query)}" data-filter="query"></div><select class="input" aria-label="장 필터" data-filter="chapter">${opts([['all','모든 강의자료'],...data.map(c=>[c.chapter,`${c.chapter}장 · ${c.title}`])],filters.chapter)}</select>${kind==='concept'?`<select class="input" aria-label="개념 학습 상태" data-filter="status">${opts([['all','모든 학습 상태'],['unseen','미완료 개념'],['learned','완료 개념']],filters.status)}</select>`:`<select class="input" aria-label="문제 유형" data-filter="type">${opts([['all','모든 문제 유형'],...Object.entries(TYPES)],filters.type)}</select><select class="input" aria-label="난이도" data-filter="difficulty">${opts([['all','모든 난이도'],['기본','기본'],['응용','응용'],['심화','심화']],filters.difficulty)}</select><select class="input" aria-label="문제 학습 상태" data-filter="status">${opts([['all','모든 학습 상태'],['unseen','아직 안 푼 문제'],['wrong','최근 틀린 문제'],['bookmarked','북마크']],filters.status)}</select>`}<div class="filter-footer"><span>필요한 장·유형·핵심어로 문제를 찾아보세요.</span><button data-action="reset-filter">필터 초기화</button></div></div>`;
}
function filterQuestions(){const text=filters.query.trim().toLowerCase();return questions.filter(q=>(filters.chapter==='all'||q.chapter===Number(filters.chapter))&&(filters.type==='all'||q.type===filters.type)&&(filters.difficulty==='all'||q.difficulty===filters.difficulty)&&(filters.concept==='all'||q.conceptId===filters.concept)&&(!text||[q.prompt,byConcept.get(q.conceptId)?.title,...(q.keywords||[])].join(' ').toLowerCase().includes(text))&&(filters.status==='all'||(filters.status==='unseen'&&(!state.attempts[q.id]||state.attempts[q.id].needsReview))||(filters.status==='wrong'&&state.attempts[q.id]&&!state.attempts[q.id].correct)||(filters.status==='bookmarked'&&state.bookmarks.includes(q.id))));}
function chapterCourses(kind='concepts'){return `<div class="chapter-course-grid">${data.map(ch=>{
 const qs=questions.filter(q=>q.chapter===ch.chapter),read=ch.concepts.filter(c=>state.learned.includes(c.id)).length,done=qs.filter(q=>state.attempts[q.id]&&!state.attempts[q.id].needsReview).length;
 const readLink=link(`${ch.chapter}장 개념 한 번에 읽기 ${icon('arrow')}`,`chapter/${ch.chapter}`,kind==='questions'?'secondary':'');const problemLink=link(`${qs.length}문항 한 페이지로 풀기`,`worksheet/${ch.chapter}`,kind==='questions'?'':'secondary');
 return `<article class="surface chapter-course"><div class="spread"><div class="eyebrow">CHAPTER ${String(ch.chapter).padStart(2,'0')}</div><span class="pill ${read===ch.concepts.length?'':'gray'}">${read===ch.concepts.length?'✓ 읽기 완료':read?'일부 읽음':'학습 전'}</span></div><h2><span>${ch.chapter}장</span> ${e(ch.title)}</h2><p>${kind==='questions'?'문제를 스크롤하며 풀고, 각 문제 아래에서 정답과 해설을 확인합니다.':'이 장의 정의·원리·예시·오답 포인트를 한 페이지에서 이어서 읽습니다.'}</p><div class="chapter-course-meta"><span>${ch.slideCount}슬라이드</span><span>${qs.length}문항</span></div><div class="progress"><i style="width:${read/ch.concepts.length*100}%"></i></div><div class="spread note"><span>개념 읽기 ${Math.round(read/ch.concepts.length*100)}%</span><span>문제 ${done} / ${qs.length} 풀이</span></div><div class="actions section-gap">${kind==='questions'?problemLink+readLink:readLink+problemLink}</div></article>`;
 }).join('')}</div>`;}
function chapterNavigation(chapter){return `<nav class="chapter-reading-nav no-print" aria-label="개념 학습 장 선택">${data.map(ch=>`<a href="#/chapter/${ch.chapter}" class="${ch.chapter===chapter?'active':''}" ${ch.chapter===chapter?'aria-current="page"':''}>${ch.chapter}장 <span>${e(ch.title)}</span></a>`).join('')}</nav>`;}
function chapterReadingActions(ch){const qs=questions.filter(q=>q.chapter===ch.chapter),complete=ch.concepts.every(c=>state.learned.includes(c.id));return `<div class="actions">${btn(`이 장 ${qs.length}문항 스크롤로 풀기 ${icon('arrow')}`,'chapter-practice',`data-value="${ch.chapter}"`)}${btn(complete?'✓ 이 장 읽기 완료 · 취소':'이 장 읽기 완료','chapter-learned',`data-value="${ch.chapter}" aria-pressed="${complete}"`,'secondary')}</div>`;}
function chapterPage(chapter=Number(routeId)){
 const ch=data.find(ch=>ch.chapter===chapter);if(!ch)return empty('장을 찾을 수 없습니다.','1~4장 중에서 선택해 주세요.',link('장별 개념 학습','concepts'));
 return `<a class="back-link" href="#/concepts">${icon('back')} 1~4장 목록으로</a>${title(`CHAPTER ${String(ch.chapter).padStart(2,'0')} · CONCEPT READING`,`${ch.chapter}장 · ${e(ch.title)}`,'이 장의 내용을 모두 펼쳐 두었습니다. 아래로 스크롤하며 순서대로 읽어 보세요.',btn(`${icon('print')} 이 장 인쇄 / PDF`,'print','','secondary'))}${chapterNavigation(ch.chapter)}<div class="surface chapter-reading-bar"><p class="note">전체 개념을 한 번에 읽고, 이 장의 문제를 끊김 없이 이어서 풀 수 있습니다.</p>${chapterReadingActions(ch)}</div><article class="surface chapter-reader concept-body">${ch.concepts.map((c,i)=>`<section id="concept-${c.id}" class="chapter-text" aria-labelledby="heading-${c.id}"><div class="eyebrow">${ch.chapter}장 · ${String(i+1).padStart(2,'0')}</div><h2 id="heading-${c.id}">${e(c.title)}</h2><div class="definition">${e(c.summary)}</div><h3>꼭 이해할 내용</h3><ul>${c.details.map(t=>`<li>${e(t)}</li>`).join('')}</ul>${c.examples?.length?`<h3>예시로 연결하기</h3><ul>${c.examples.map(t=>`<li>${e(t)}</li>`).join('')}</ul>`:''}${c.pitfalls?.length?`<h3>확실히 구분하기</h3><div class="notice warm"><ul>${c.pitfalls.map(t=>`<li>${e(t)}</li>`).join('')}</ul></div>`:''}</section>`).join('')}</article><div class="surface chapter-reading-bar section-gap">${chapterReadingActions(ch)}</div><div class="question-nav no-print">${ch.chapter>1?link(`${icon('back')} ${ch.chapter-1}장 읽기`,`chapter/${ch.chapter-1}`,'secondary'):link('1~4장 목록','concepts','secondary')}${ch.chapter<4?link(`${ch.chapter+1}장 읽기 ${icon('arrow')}`,`chapter/${ch.chapter+1}`):link('실전 모의고사','exam')}</div>`;
}
function questionCards(list){if(!list.length)return empty('조건에 맞는 문제가 없습니다.','검색어나 필터를 바꿔 보세요.',btn('필터 초기화','reset-filter','','secondary'));const pages=Math.ceil(list.length/24);page=Math.max(0,Math.min(page,pages-1));return `<div class="q-grid">${list.slice(page*24,(page+1)*24).map(q=>{const a=state.attempts[q.id];return `<button class="q-card" data-action="open-question" data-id="${q.id}"><div class="q-tags"><span class="qid">${e(q.id.toUpperCase())}</span><span class="pill ${q.type==='essay'?'gold':'gray'}">${TYPES[q.type]}</span><span class="pill">${e(q.difficulty)}</span>${state.bookmarks.includes(q.id)?icon('bookmark'):''}</div><h3>${e(q.prompt)}</h3><footer><span>${q.chapter}장 · ${e(byConcept.get(q.conceptId)?.title)}</span><span>${a?(a.needsReview?'개정 문항 · 재확인':a.correct?'✓ 정답':'↻ 복습 필요'):'○ 미풀이'}</span></footer></button>`;}).join('')}</div>${pages>1?`<div class="page-nav">${btn('이전','page',`data-dir="-1" ${page===0?'disabled':''}`,'secondary tiny')}<span>${page+1} / ${pages} 페이지 · ${list.length}문항</span>${btn('다음','page',`data-dir="1" ${page===pages-1?'disabled':''}`,'secondary tiny')}</div>`:''}`;}
function revisionNotice(){const n=Object.values(state.attempts).filter(a=>a.needsReview).length;return n?notice(`검수로 기존 ${n}개 문항의 내용이나 채점 기준이 개정됐습니다. 이전 답안과 메모는 보관했으며, 다시 풀기 전까지 현재 정답률에서 제외합니다. <a href="#/wrong">재확인할 문항 보기 →</a>`,true):'';}
function bankPage(){return `${title('QUESTION LEARNING PATH','문제로 공부하는 컴퓨터보안',`1~4장 ${questions.length}문항을 풀며 정답의 이유와 개념을 함께 익히고, 서술형은 핵심 키워드로 직접 써 보세요.`,btn(`무작위 20문항 ${icon('arrow')}`,'random'))}${revisionNotice()}${cramShortcut()}${hero()}${statCards()}<div class="tabs" role="group" aria-label="문제 학습 방식"><button class="tab ${bankMode==='course'?'active':''}" data-action="bank-mode" data-value="course" aria-pressed="${bankMode==='course'}">장별 문제 학습 <span>${data.length}장</span></button><button class="tab ${bankMode==='all'?'active':''}" data-action="bank-mode" data-value="all" aria-pressed="${bankMode==='all'}">전체 문제은행 <span>${questions.length}</span></button></div>${bankMode==='course'?`<div class="list-meta">장을 선택하면 모든 문제를 한 페이지에서 풀고 해설을 확인할 수 있습니다.</div>${chapterCourses('questions')}`:`${chapterCards()}${searchFilters()}<div class="list-meta spread"><span>${filterQuestions().length}개 문항${filters.concept!=='all'?` · ${e(byConcept.get(filters.concept)?.title)}`:''}</span>${btn('이 결과 모두 풀기','filtered','','secondary tiny')}</div>${questionCards(filterQuestions())}`}`;}
function conceptsPage(){return `${title('CHAPTER CONCEPT NOTE','개념학습도, 1장부터 4장까지.','각 장 안의 정의, 원리, 예시와 혼동 포인트를 한 페이지에 모았습니다. 장을 한 번 선택한 뒤 스크롤하며 읽어 보세요.')}${chapterCourses()}`;}
function conceptPage(){const c=byConcept.get(routeId);return c?chapterPage(c.chapter):empty('개념을 찾을 수 없습니다.','장 목록에서 다시 선택해 주세요.',link('장별 개념 학습','concepts'));}
function cramShortcut(){return cramData?.topics?.length?`<section class="cram-shortcut"><div><b>시간이 부족하다면, 벼락치기 핵심 ${cramData.topics.length}주제</b><p>기출과 현재 자료를 기준으로 우선 공부할 내용을 추려 암기 답안과 예상문제로 정리했습니다.</p></div>${link('핵심만 공부하기','cram')}</section>`:'';}
function cramQuestions(){return cramData?.topics?.flatMap(t=>t.questions)||[];}
function cramQuestion(q){
 const hidden=state.cram.hidden.includes(q.id),answer=state.cram.answers[q.id],isChoice=q.type==='mcq';
 const input=isChoice?`<div class="options" role="group" aria-label="${e(q.id)} 답 선택">${q.options.map((o,i)=>`<button class="option ${answer===i?'selected':''}" data-action="cram-choice" data-id="${q.id}" data-value="${i}" aria-pressed="${answer===i}"><span class="option-index">${i+1}</span><span>${e(o.text)}</span></button>`).join('')}</div>`:`<label class="note" for="cram-answer-${q.id}">핵심어를 연결해 직접 써 보세요.</label><textarea id="cram-answer-${q.id}" class="input cram-answer" rows="3" data-input="cram-answer" data-id="${q.id}">${e(typeof answer==='string'?answer:'')}</textarea>`;
 const model=isChoice?`<p class="cram-key"><b>정답 ${q.answer+1}번</b>${Number.isInteger(answer)?` · 내 선택 ${answer+1}번`:''}</p>${q.options.map((o,i)=>`<div class="option-explanation ${i===q.answer?'correct':''}"><b>${i+1}번 · ${i===q.answer?'정답':'오답'}</b><p>${e(o.explanation)}</p></div>`).join('')}`:`<div class="model-answer">${e(q.answer)}</div>`;
 return `<section class="cram-question" id="${q.id}" aria-labelledby="heading-${q.id}"><div class="flex"><span class="pill ${q.label==='범위 내 변형'?'gray':'gold'}">${e(q.label)}</span><span class="note">${TYPES[q.type]}</span></div><h3 id="heading-${q.id}">${e(q.prompt)}</h3><div class="cram-input no-print">${input}</div><div class="actions no-print">${btn(hidden?'모범답안·해설 보기':'모범답안·해설 가리기','cram-reveal',`data-id="${q.id}" aria-expanded="${!hidden}"`,'secondary tiny')}</div>${hidden?'':`<div class="cram-feedback" aria-label="${e(q.id)} 모범답안과 해설">${model}${q.rubric?.length?`<div class="cram-checks"><b>답안에서 빠뜨리지 않을 것</b><ul>${q.rubric.map(item=>`<li>${e(item)}</li>`).join('')}</ul></div>`:''}${q.explanation&&q.explanation!==q.answer?`<p class="cram-explanation">${e(q.explanation)}</p>`:''}</div>`}</section>`;
}
function cramPage(){
 if(!cramData?.topics?.length)return empty('벼락치기 자료를 불러오지 못했습니다.','페이지를 새로고침해 주세요.',link('문제은행','bank'));
 const topics=cramData.topics,list=topics.filter(t=>!state.cram.onlyPending||!state.cram.remembered.includes(t.id)),count=cramQuestions().length;
 return `${title('LAST-MINUTE STUDY',`벼락치기 핵심 ${topics.length}주제`,cramData.selectionNote,btn(`${icon('print')} 암기 정리 인쇄`,'print','','secondary'))}<section class="surface cram-plan"><div><span class="eyebrow">기출을 이렇게 읽었습니다</span><h2>정의하고, 비교하고, 순서대로 설명하기</h2><ul>${cramData.patterns.map(p=>`<li><b>${e(p.title)}</b><span>${e(p.observation)}</span></li>`).join('')}</ul></div><div class="cram-plan-side"><strong>${topics.length}<small>주제</small> / ${count}<small>예상문항</small></strong><p>암기 줄과 용어의 뜻 읽기<br>모범답안을 내 말로 설명하기<br>가리고 직접 쓴 뒤 빠진 요소 확인</p></div></section><details class="surface pad cram-evidence"><summary>주제 선정 근거와 이번에 제외한 내용</summary><p class="note">${e(cramData.evidenceNote)}</p><div class="table-wrap"><table><thead><tr><th>선정 주제</th><th>실제 기출과 연결</th></tr></thead><tbody>${topics.map(t=>`<tr><td>${e(t.title)}</td><td>${t.evidence.map(x=>`<b>${x.exam==='midterm'?'중간':'기말'} ${x.numbers.join('·')}번</b> · ${e(x.observation)}`).join('<br>')}</td></tr>`).join('')}</tbody></table></div><p class="note section-gap">${e(cramData.exclusionNote)}</p></details><div class="surface cram-toolbar no-print"><div><b>해설 없이 설명 가능 ${state.cram.remembered.length} / ${topics.length}주제</b><p>암기 체크와 작성 답안은 자동 저장됩니다.</p></div><div class="actions">${btn('가리고 직접 쓰기','cram-recall',`aria-pressed="${state.cram.recall}"`,'secondary tiny')}${btn('암기 답안 모두 펼치기','cram-learn',`aria-pressed="${!state.cram.recall}"`,'secondary tiny')}${btn(state.cram.onlyPending?'모든 주제 보기':'아직 못 외운 주제만','cram-pending',`aria-pressed="${state.cram.onlyPending}"`,'secondary tiny')}</div></div><nav class="cram-jumps no-print" aria-label="벼락치기 주제 이동">${list.map(t=>btn(`${t.id.slice(-2)} ${e(t.title)}`,'cram-jump',`data-id="${t.id}"`,'secondary tiny')).join('')}</nav>${!state.cram.recall&&list.length?`<section class="surface cram-quick" aria-label="시험 직전 핵심 암기표"><div class="eyebrow">QUICK RECALL</div><h2>시험 직전, 이 ${list.length}줄</h2><ol>${list.map(t=>`<li><b>${e(t.title)}</b><p>${e(t.memoryLine)}</p></li>`).join('')}</ol></section>`:''}${list.length?list.map(t=>`<article class="surface cram-topic" id="${t.id}" aria-labelledby="heading-${t.id}"><header><div><div class="eyebrow">PRIORITY ${t.id.slice(-2)} · ${t.chapter}장</div><span class="pill ${t.evidenceType==='style-transfer'?'gold':'gray'}">${t.evidenceType==='style-transfer'?'현재 자료 · 성향 적용':'기출과 현재 범위의 교집합'}</span><h2 id="heading-${t.id}">${e(t.title)}</h2><p class="cram-reason">${e(t.priorityReason)}</p></div>${btn(state.cram.remembered.includes(t.id)?'✓ 해설 없이 설명 가능':'해설 없이 설명 가능','cram-remember',`data-id="${t.id}" aria-pressed="${state.cram.remembered.includes(t.id)}"`,'secondary tiny no-print')}</header>${state.cram.recall?`<p class="note cram-recall-note">키워드를 연결해 답안을 써 본 뒤 모범답안과 비교하세요.</p>`:`<section class="cram-memory" aria-label="${e(t.title)} 암기 정리"><h3>이 줄부터 외우기</h3><p>${e(t.memoryLine)}</p><dl class="keyword-definitions">${t.essentials.map(k=>`<div><dt>${e(k.term)}</dt><dd>${e(k.explanation)}</dd></div>`).join('')}</dl></section>`}${t.questions.map(cramQuestion).join('')}</article>`).join(''):empty(`${topics.length}주제 모두 설명 가능으로 표시했습니다.`,'가리고 직접 쓸 수 있는지 한 번 더 확인해 보세요.',btn('모든 주제 보기','cram-pending','','secondary'))}`;
}
function refreshCramQuestion(q){const card=document.getElementById(q.id);if(card){const y=window.scrollY;card.outerHTML=cramQuestion(q);window.scrollTo({top:y,behavior:'instant'});}}
function cramAction(action,id,value){
 if(action==='cram-jump'){document.getElementById(id)?.scrollIntoView({block:'start'});return;}
 if(action==='cram-choice'||action==='cram-reveal'){const q=cramQuestions().find(q=>q.id===id);if(!q)return;if(action==='cram-choice'){const n=Number(value);if(q.type!=='mcq'||!Number.isInteger(n)||n<0||n>=q.options.length)return;state.cram.answers[id]=n;}else state.cram.hidden=state.cram.hidden.includes(id)?state.cram.hidden.filter(x=>x!==id):[...state.cram.hidden,id];save();refreshCramQuestion(q);return;}
 if(action==='cram-recall'){state.cram.recall=true;state.cram.hidden=cramQuestions().map(q=>q.id);}
 else if(action==='cram-learn'){state.cram.recall=false;state.cram.hidden=[];}
 else if(action==='cram-pending')state.cram.onlyPending=!state.cram.onlyPending;
 else if(action==='cram-remember'){if(!cramData?.topics?.some(t=>t.id===id))return;state.cram.remembered=state.cram.remembered.includes(id)?state.cram.remembered.filter(x=>x!==id):[...state.cram.remembered,id];}
 else return;
 const y=window.scrollY;save();render();window.scrollTo({top:y,behavior:'instant'});
}
function writingGuide(q){const guide=q.writingGuide;if(q.type!=='essay'||!guide?.keywords?.length)return '';return `<section class="writing-guide" data-guide-for="${q.id}" aria-label="서술형 답안 작성 가이드"><h4>핵심 키워드와 뜻</h4><dl class="keyword-definitions">${guide.keywords.map(k=>`<div><dt>${e(k.term)}</dt><dd>${e(k.explanation)}</dd></div>`).join('')}</dl><h4>답안 구성 순서</h4><ol class="answer-outline">${guide.answerOutline.map(step=>`<li>${e(step)}</li>`).join('')}</ol></section>`;}
function conceptRecap(q){const c=byConcept.get(q.conceptId);if(!c)return '';return `<section class="concept-recap" data-concept-id="${c.id}" aria-label="문제 속 핵심 개념"><div class="eyebrow">이 문제에서 익힐 개념</div><h4>${e(c.title)}</h4><p class="recap-definition">${e(c.summary)}</p><ul>${c.details.map(t=>`<li>${e(t)}</li>`).join('')}</ul>${c.examples?.length?`<h5>예시로 적용하기</h5><ul>${c.examples.map(t=>`<li>${e(t)}</li>`).join('')}</ul>`:''}${c.pitfalls?.length?`<h5>확실히 구분하기</h5><ul>${c.pitfalls.map(t=>`<li>${e(t)}</li>`).join('')}</ul>`:''}</section>`;}
function keywordHint(q,d){if(q.type!=='essay'||!q.writingGuide?.keywords?.length||d.revealed)return '';return `<div class="essay-hint no-print">${btn(d.hintVisible?'키워드 힌트 접기':'핵심 키워드 힌트','worksheet-hint',`data-id="${q.id}" aria-expanded="${d.hintVisible}"`,'secondary tiny')}${d.hintVisible?`<div class="keyword-chips" aria-label="답안 작성 키워드">${q.writingGuide.keywords.map(k=>`<span>${e(k.term)}</span>`).join('')}</div>`:''}</div>`;}
function worksheetQuestions(){return routeId==='selection'?practiceQueue.map(id=>byId.get(id)).filter(Boolean):questions.filter(q=>q.chapter===Number(routeId));}
function worksheetDraft(q){return state.worksheet[q.id]||(state.worksheet[q.id]=emptyWorksheetDraft(q));}
function worksheetNavigation(chapter){return `<nav class="chapter-reading-nav no-print" aria-label="문제 풀이 장 선택">${data.map(ch=>`<a href="#/worksheet/${ch.chapter}" class="${ch.chapter===chapter?'active':''}" ${ch.chapter===chapter?'aria-current="page"':''}>${ch.chapter}장 <span>${e(ch.title)} · ${ch.questions.length}문항</span></a>`).join('')}</nav>`;}
function worksheetSummary(list){const drafts=list.map(q=>state.worksheet[q.id]);return `채점 ${drafts.filter(d=>d?.graded).length} / ${list.length}문항 · 완전 정답 ${drafts.filter(d=>d?.graded&&d.score===1).length}문항`;}
function worksheetPage(){
 const list=worksheetQuestions(),ch=data.find(ch=>ch.chapter===Number(routeId));
 if(!list.length)return empty('표시할 문제가 없습니다.','장을 선택해 문제를 펼쳐 보세요.',link('장별 학습','bank'));
 return `${title('SCROLL & SOLVE',ch?`${ch.chapter}장 · ${e(ch.title)} 문제`:'선택한 문제 모아 풀기',`${list.length}문항을 모두 펼쳤습니다. 답을 작성한 뒤 각 문제 아래에서 정답과 핵심 개념을 함께 익히고, 서술형은 키워드를 연결해 직접 써 보세요.`,ch?link('이 장 개념 읽기',`chapter/${ch.chapter}`,'secondary'):'')}${worksheetNavigation(ch?.chapter)}<div class="surface worksheet-summary worksheet-toolbar"><span data-worksheet-summary aria-live="polite">${worksheetSummary(list)}</span><div class="actions">${btn('정답·해설 모두 펼치기','worksheet-expand-all','','secondary tiny')}${btn('모두 접기','worksheet-collapse-all','','secondary tiny')}</div></div><div class="worksheet-list">${list.map((q,i)=>worksheetCard(q,i)).join('')}</div><div class="actions section-gap">${link('장별 학습 목록','bank','secondary')}${ch&&ch.chapter<4?link(`${ch.chapter+1}장 문제 펼치기 ${icon('arrow')}`,`worksheet/${ch.chapter+1}`):link('실전 모의고사','exam')}</div>`;
}
function worksheetCard(q,index){
 const d=worksheetDraft(q),locked=d.revealed||d.graded,hasAnswer=worksheetHasAnswer(q,d),inputId='worksheet-answer-'+q.id;
 const result=d.graded?(d.score===1?'정답입니다':d.score===0?'다시 익힐 부분이 있습니다':`부분 정답 · ${Math.round(d.score*100)}%`):'정답과 해설';
 const input=q.options.length?`<div class="options" role="group" aria-label="${index+1}번 답 선택">${q.options.map((o,i)=>`<button class="option ${d.choice===i?'selected':''} ${d.revealed?(i===q.answer?'correct':d.choice===i?'incorrect':''):''}" aria-pressed="${d.choice===i}" data-action="worksheet-choice" data-id="${q.id}" data-value="${i}" ${locked?'disabled':''}><span class="option-index">${q.type==='ox'?e(o.text):i+1}</span><span>${e(q.type==='ox'?(o.text==='O'?'옳다':'틀리다'):o.text)}</span></button>`).join('')}</div>`:`<label class="note" for="${inputId}">${q.type==='essay'?'핵심 개념과 이유를 내 문장으로 작성해 보세요.':q.shortForm==='multi-part'?'요구한 항목을 순서대로 모두 적어 보세요.':'정답을 직접 적어 보세요.'}</label><textarea id="${inputId}" class="input answer-text worksheet-answer" data-input="worksheet-answer" data-id="${q.id}" maxlength="12000" placeholder="여기에 답안을 작성하세요." ${locked?'readonly':''}>${e(d.text)}</textarea>`;
 return `<article class="surface worksheet-question" id="worksheet-${q.id}" aria-labelledby="worksheet-heading-${q.id}"><div class="question-head"><span class="pill gray">${index+1}번</span><span class="pill">${q.chapter}장</span><span class="pill gold">${TYPES[q.type]}</span><span class="pill gray">${e(q.difficulty)}</span>${d.graded?`<span class="pill ${d.score===1?'':'red'}">${Math.round(d.score*100)}%</span>`:''}<button class="bookmark ${state.bookmarks.includes(q.id)?'on':''}" aria-label="${index+1}번 북마크 ${state.bookmarks.includes(q.id)?'해제':'추가'}" data-action="worksheet-bookmark" data-id="${q.id}">${icon('bookmark')}</button></div><h2 id="worksheet-heading-${q.id}" class="question-prompt">${e(q.prompt)}</h2>${keywordHint(q,d)}${input}<div class="submit-row">${!d.revealed?btn(d.graded?'정답·해설 다시 보기':hasAnswer?'답안 채점 · 정답·해설 보기':'정답·해설 보기','worksheet-show',`data-id="${q.id}"`):btn('해설 접기','worksheet-hide',`data-id="${q.id}"`,'secondary')}${locked?btn('이 문제 다시 풀기','worksheet-retry',`data-id="${q.id}"`,'secondary tiny'):'<span class="note">답안은 자동 저장됩니다.</span>'}</div>${d.revealed?`<section class="feedback" id="worksheet-feedback-${q.id}" aria-label="${index+1}번 정답과 해설"><h3 class="${d.graded&&d.score<1?'wrong':''}">${result}</h3>${!q.options.length?`<div class="model-answer"><b>모범답안</b>
${e(q.answer)}</div>`:`<div class="answer-key"><b>정답 ${q.type==='ox'?e(q.options[q.answer].text):q.answer+1+'번'}</b> · ${e(q.options[q.answer].text)}</div>`}${q.type==='essay'&&hasAnswer?`${rubricHTML(q,d.rubric,'worksheet-rubric',d.graded)}${!d.graded?btn('자기평가 점수 기록','worksheet-grade',`data-id="${q.id}"`):''}`:''}${q.type==='short'&&d.graded&&d.score<1?`<div class="actions section-gap">${btn('동일한 뜻의 답안 · 정답으로 인정','worksheet-accept',`data-id="${q.id}"`,'secondary tiny')}</div>`:''}${allExplanations(q)}${q.type==='essay'&&q.writingGuide?`<div class="actions section-gap">${btn('키워드 보고 다시 쓰기','worksheet-recall',`data-id="${q.id}"`,'secondary')}</div>`:''}<div class="section-gap"><label class="small" for="worksheet-note-${q.id}">나의 오답 메모</label><textarea id="worksheet-note-${q.id}" class="input" rows="2" data-input="personal-note" data-id="${q.id}">${e(state.notes[q.id]||'')}</textarea></div></section>`:''}</article>`;
}
function refreshWorksheetCard(q){const list=worksheetQuestions(),index=list.findIndex(item=>item.id===q.id),card=document.getElementById('worksheet-'+q.id);if(!card||index<0)return;const y=window.scrollY;card.outerHTML=worksheetCard(q,index);document.querySelectorAll('[data-worksheet-summary]').forEach(el=>el.textContent=worksheetSummary(list));const count=document.querySelector('.nav a[href="#/wrong"] .count');if(count)count.textContent=wrong().length;window.scrollTo({top:y,behavior:'instant'});}
function worksheetAction(action,id,el,value){
 const q=byId.get(id);if(!q)return;let d=worksheetDraft(q);
 if(action==='worksheet-choice'){if(d.revealed||d.graded)return;d.choice=Number(value);}
 else if(action==='worksheet-show'){if(!d.graded){d=evaluateWorksheet(q,d);state.worksheet[id]=d;if(d.graded)recordAttempt(state,q,q.options.length?d.choice:d.text,d.score);}else d.revealed=true;}
 else if(action==='worksheet-hide')d.revealed=false;
 else if(action==='worksheet-hint'){if(q.type!=='essay'||d.revealed)return;d.hintVisible=!d.hintVisible;}
 else if(action==='worksheet-recall'){if(q.type!=='essay')return;state.worksheet[id]={...emptyWorksheetDraft(q),hintVisible:true};}
 else if(action==='worksheet-retry')state.worksheet[id]=emptyWorksheetDraft(q);
 else if(action==='worksheet-rubric'){if(d.graded)return;const n=Number(el.dataset.index);d.rubric=el.checked?[...new Set([...d.rubric,n])]:d.rubric.filter(x=>x!==n);save();return;}
 else if(action==='worksheet-grade'){if(d.graded||!worksheetHasAnswer(q,d))return;d=evaluateWorksheet(q,d,true);state.worksheet[id]=d;recordAttempt(state,q,d.text,d.score,true);}
 else if(action==='worksheet-accept'){if(q.type!=='short'||!d.graded)return;d.accepted=true;d.score=1;recordAttempt(state,q,d.text,1,true);}
 else if(action==='worksheet-bookmark')state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];
 save();refreshWorksheetCard(q);if(action==='worksheet-hint')document.querySelector(`[data-action="worksheet-hint"][data-id="${q.id}"]`)?.focus({preventScroll:true});if(action==='worksheet-recall'){document.getElementById('worksheet-'+q.id)?.scrollIntoView({block:'start'});document.querySelector(`[data-input="worksheet-answer"][data-id="${q.id}"]`)?.focus({preventScroll:true});}
}
function questionInput(q,answer,exam=false){
 const inputId=exam==='revision'?`revision-answer-${q.id}`:'answer-text';
 if(q.type==='mcq'||q.type==='ox')return `<div class="options" role="group" aria-label="답 선택">${q.options.map((o,i)=>`<button class="option ${answer===i?'selected':''} ${!exam&&practice.revealed?(i===q.answer?'correct':answer===i?'incorrect':''):''}" aria-pressed="${answer===i}" data-action="${exam==='revision'?'revision-choice':exam?'exam-choice':'choice'}" data-id="${q.id}" data-value="${i}" ${!exam&&practice.revealed?'disabled':''}><span class="option-index">${q.type==='ox'?e(o.text):i+1}</span><span>${e(q.type==='ox'?(o.text==='O'?'옳다':o.text==='X'?'틀리다':o.text):o.text)}</span></button>`).join('')}</div>`;
 return `<label for="${inputId}" class="note">${q.type==='essay'?'정의 → 원리 / 비교 → 근거 / 대책 순으로 작성해 보세요.':(q.shortForm==='multi-part'?'요구한 항목을 빠짐없이 순서대로 적어 보세요.':'핵심 용어를 정확히 적어 보세요.')}</label><textarea id="${inputId}" class="input answer-text" placeholder="답안을 직접 작성하세요. 제출 전에는 모범답안이 보이지 않습니다." data-input="${exam==='revision'?'revision-answer':exam?'exam-answer':'practice-answer'}" data-id="${q.id}" ${!exam&&practice.revealed?'readonly':''}>${e(answer??'')}</textarea><div class="note" style="margin-top:6px">${q.type==='essay'?'서술형은 모범답안과 채점 요소를 대조해 직접 평가합니다.':'단답형은 등록된 동의어를 비교합니다. 복합 단답은 요구한 모든 항목을 적어야 합니다. 명령어·경로·방향 표기의 기호와 단어 구분도 확인하세요.'}</div>`;
}
function allExplanations(q){return `${q.options.length?`<h4 style="font-size:12px;margin:20px 0 10px">선택지 하나하나 이해하기</h4>${/옳지|잘못|아닌|틀린/.test(q.prompt)?'<p class="note">이 문제는 잘못된 설명을 고릅니다. 정답 표시는 질문의 조건을 만족하는 선택지를 뜻합니다.</p>':''}${q.options.map((o,i)=>`<div class="option-explanation ${i===q.answer?'correct':''}"><div class="option-label"><span class="pill ${i===q.answer?'':'gray'}">${i===q.answer?'정답':'오답'}</span><span>보기 ${i+1}</span></div><div class="option-text">${e(o.text)}</div><div>${e(o.explanation)}</div></div>`).join('')}`:''}${q.options.length||String(q.explanation).trim()!==String(q.answer).trim()?`<div class="explain">${e(q.explanation)}</div>`:''}${writingGuide(q)}${conceptRecap(q)}`;}
function rubricHTML(q,checked,action,disabled=false){const rubric=q.rubric?.length?q.rubric:[String(q.answer)];return `<div class="rubric"><h4>내 답안에 포함한 채점 요소를 체크하세요.</h4><div class="note">표현이 달라도 원리와 근거가 맞으면 인정합니다. 체크한 요소 수로 부분점수를 계산합니다.</div>${rubric.map((r,i)=>`<label><input type="checkbox" data-action="${action}" data-id="${q.id}" data-index="${i}" ${checked.includes(i)?'checked':''} ${disabled?'disabled':''}><span>${e(r)}</span></label>`).join('')}</div>`;}
function practicePage(){const q=byId.get(routeId);if(!q)return empty('문항을 찾을 수 없습니다.','문제은행에서 문제를 선택해 주세요.',link('문제은행','bank'));if(!practiceQueue.includes(q.id))setQueue(questions);const index=practiceQueue.indexOf(q.id),prev=practiceQueue[index-1],next=practiceQueue[index+1];
 const canSubmit=q.options.length?practice.choice!==null:practice.text.trim().length>0;
 const gradeLabel=practice.graded?(practice.score===1?'정답입니다':practice.score===0?'다시 익힐 부분이 있습니다':`부분 정답 · ${Math.round(practice.score*100)}%`):'모범답안과 비교해 보세요';
 return `<div class="chapter-backlinks">${practiceQueue.every(id=>byId.get(id)?.chapter===q.chapter)?`<a class="back-link" href="#/concept/${q.conceptId}">${icon('back')} ${q.chapter}장 개념학습으로</a>`:''}<a class="back-link" href="#/bank">${icon('back')} 문제은행으로</a></div><div class="two-col"><div><div class="surface pad"><div class="question-head"><span class="pill gray">${index+1} / ${practiceQueue.length}</span><span class="pill">${q.chapter}장</span><span class="pill gold">${TYPES[q.type]}</span><span class="pill gray">${e(q.difficulty)}</span><button class="bookmark ${state.bookmarks.includes(q.id)?'on':''}" aria-label="${state.bookmarks.includes(q.id)?'북마크 해제':'북마크 추가'}" data-action="bookmark" data-id="${q.id}">${icon('bookmark')}</button></div><h1 class="question-prompt">${e(q.prompt)}</h1>${questionInput(q,q.options.length?practice.choice:practice.text)}${!practice.revealed?`<div class="submit-row"><span class="note">${q.options.length?'답을 선택한 뒤 제출하세요.':'답안을 작성한 뒤 모범답안을 확인하세요.'}</span>${btn(`${q.type==='essay'?'답안 제출 · 모범답안 확인':'답안 제출'} ${icon('arrow')}`,'submit',canSubmit?'':'disabled')}</div>`:`<section class="feedback" aria-live="polite"><h3 class="${practice.graded&&practice.score<1?'wrong':''}">${gradeLabel}</h3>${q.options.length?'':`<div class="model-answer"><b>모범답안</b>\n${e(q.answer)}</div>`}${q.type==='essay'?`${rubricHTML(q,practice.rubric,'rubric',practice.graded)}${!practice.graded?btn('자기평가 점수 기록','grade-essay'):notice(`자기평가 ${Math.round(practice.score*100)}%가 학습 기록에 반영됐습니다.`)}`:''}${q.type==='short'?`<div class="actions section-gap">${btn('동일한 의미의 답안 · 정답으로 인정','override-short',practice.score===1?'disabled':'','secondary tiny')}</div><p class="note section-gap">자동 비교가 인식하지 못한 동의어는 모범답안과 뜻이 같은지 확인한 뒤 정답으로 인정할 수 있습니다.</p>`:''}${allExplanations(q)}<div class="section-gap"><label for="personal-note" class="small"><b>나의 오답 메모</b></label><textarea id="personal-note" class="input" rows="3" data-input="personal-note" data-id="${q.id}" placeholder="헷갈렸던 이유를 한 줄로 남겨 보세요.">${e(state.notes[q.id]||'')}</textarea><div class="note">입력하면 이 브라우저에 자동 저장됩니다.</div></div><div class="actions section-gap">${btn('같은 문제 다시 풀기','retry','','secondary tiny')}</div></section>`}</div><div class="question-nav">${btn(`${icon('back')} 이전 문제`,'practice-nav',`data-id="${prev||''}" ${!prev?'disabled':''}`,'secondary')}${btn(`다음 문제 ${icon('arrow')}`,'practice-nav',`data-id="${next||''}" ${!next||(q.type==='essay'&&practice.revealed&&!practice.graded)?'disabled':''}`)}</div></div><aside class="surface side-list sticky"><h3>이 문제의 학습 목표</h3><p class="small">${practice.revealed?e(byConcept.get(q.conceptId)?.title):e(CHAPTER_TITLES[q.chapter])+" · 핵심 원리 떠올리기"}</p><p class="note" style="margin-top:12px">${practice.revealed?e(byConcept.get(q.conceptId)?.summary):'먼저 떠올려 보세요. 제출 후 관련 개념과 정답·오답의 이유를 함께 확인할 수 있습니다.'}</p><div class="progress"><i style="width:${(index+1)/practiceQueue.length*100}%"></i></div><p class="note">현재 학습 묶음 ${index+1} / ${practiceQueue.length}</p><ul class="tiny-list"><li>객관식: 틀린 보기의 실제 개념까지 확인하기</li><li>서술형: 핵심어를 사용해 내 문장으로 설명하기</li><li>부분점수 문항도 오답노트에서 다시 연습하기</li></ul></aside></div>`;
}
function dashboardPage(){const first=questions.find(q=>!state.attempts[q.id]||state.attempts[q.id].needsReview)||questions[0];return `${title('MY STUDY DASHBOARD','오늘도, 한 개념 더 정확하게.','개념을 이해하고, 정답을 골라 보고, 마지막에는 내 문장으로 설명해 보세요.')}${revisionNotice()}${hero()}${statCards()}<div class="two-col"><div><div class="spread section-title"><h2>4개 장 학습 현황</h2>${link('전체 코스 보기','bank','secondary tiny')}</div>${data.map(ch=>{const qs=questions.filter(q=>q.chapter===ch.chapter),done=qs.filter(q=>state.attempts[q.id]&&!state.attempts[q.id].needsReview).length;return `<article class="surface pad" style="margin-bottom:12px"><div class="spread"><div><div class="eyebrow">CHAPTER 0${ch.chapter}</div><h3>${e(ch.title)}</h3></div>${link('공부하기',`chapter/${ch.chapter}`,'secondary tiny')}</div><div class="progress"><i style="width:${done/qs.length*100}%"></i></div><div class="spread note"><span>${done} / ${qs.length}문항 풀이</span><span>개념 ${ch.concepts.length}개</span></div></article>`;}).join('')}</div><aside class="surface pad"><div class="eyebrow">NEXT STEP</div><h3>이번에는 직접 써 보세요</h3><p class="note section-gap">제공된 중간고사 양식의 학습 13문항 중 9개가 서술형입니다. 개념의 정의만 외우지 말고 비교 근거와 방어 원리를 설명하는 연습이 필요합니다.</p><div class="actions section-gap">${link('실전 모의고사','exam')}</div><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>나의 복습 대기</h3><p class="note section-gap">최근 오답 ${wrong().length}문항<br>북마크 ${state.bookmarks.length}문항</p>${link('오답노트 열기','wrong','secondary tiny')}</aside></div>`;}
function wrongPage(){const list=reviewTab==='bookmarked'?questions.filter(q=>state.bookmarks.includes(q.id)):wrong();return `${title('REVIEW & REMEMBER','틀린 이유까지, 내 것으로.','최근 오답·부분점수 문항과 검수 후 재확인할 문항을 모았습니다. 다시 완전히 맞히면 목록에서 빠집니다.',btn(`이 목록 다시 풀기 ${icon('arrow')}`,'review-all',list.length?'':'disabled'))}<div class="tabs"><button class="tab ${reviewTab!=='bookmarked'?'active':''}" data-action="review-tab" data-value="wrong">오답 · 부분 정답 <span>${wrong().length}</span></button><button class="tab ${reviewTab==='bookmarked'?'active':''}" data-action="review-tab" data-value="bookmarked">북마크 <span>${state.bookmarks.length}</span></button></div>${list.length?list.map(q=>{const a=state.attempts[q.id];return `<article class="surface pad" style="margin-bottom:14px"><div class="spread"><div class="flex"><span class="pill">${q.chapter}장</span><span class="pill gold">${TYPES[q.type]}</span><span class="pill gray">${e(q.id)}</span></div><button class="bookmark ${state.bookmarks.includes(q.id)?'on':''}" aria-label="북마크 전환" data-action="bookmark" data-id="${q.id}">${icon('bookmark')}</button></div><h3 style="margin:15px 0;font-size:14px;white-space:pre-wrap">${e(q.prompt)}</h3>${a?`<div class="user-answer"><span class="note">${a.needsReview?'개정 전 답안 · 당시 점수':`나의 최근 답안 · ${a.selfGraded?'자기평가':'채점'}`} ${Math.round(a.score*100)}%</span><br>${e(typeof a.answer==='number'?(a.needsReview?`개정 전 ${a.answer+1}번 보기 선택`:q.options[a.answer]?.text):a.answer)}</div>${a.needsReview?notice('정답·발문 또는 채점 기준이 보완된 문항입니다. 이전 답안과 메모는 보관하며, 다시 풀기 전까지 현재 득점률에서 제외합니다.',true):''}`:''}${state.notes[q.id]?`<p class="note">내 메모 · ${e(state.notes[q.id])}</p>`:''}<div class="actions section-gap">${btn('다시 풀기','review-question',`data-id="${q.id}"`,'tiny')}${link('개념 복습',`concept/${q.conceptId}`,'secondary tiny')}</div><details><summary>정답과 해설 펼치기</summary>${!q.options.length?`<div class="model-answer">${e(q.answer)}</div>`:''}${allExplanations(q)}</details></article>`;}).join(''):empty(reviewTab==='bookmarked'?'아직 북마크한 문제가 없습니다.':'복습할 오답이 없습니다.','문제를 풀고 어려웠던 문항을 이곳에 모아 보세요.',link('문제은행으로','bank'))}`;}
function examPage(){const ex=state.exam;if(ex?.status==='active')return examActive();if(ex?.status==='review'||ex?.status==='done')return examReview();return `${title('MOCK EXAM','교수님 양식으로, 실전처럼.','제공된 시험의 유형 비율을 반영하고, 문제 내용은 현재 PPT 1~4장 범위에서 새로 출제합니다. 중간고사 양식의 단답은 단일 답안형을 우선 선택합니다.')}<div class="surface pad exam-setup"><div class="eyebrow">CHOOSE YOUR SESSION</div><h2>오늘 연습할 시험을 선택하세요</h2><div class="mode-grid">${[['mixed','exam','중간고사 양식','13문항 · 서술 9 / 단답 1 / 객관 3'],['written','book','서술 · 단답 집중','12문항 · 서술 8 / 단답 4'],['objective','check','개념 빠른 점검','25문항 · 객관 20 / OX 5']].map(([id,ic,name,copy])=>`<button class="mode-card ${examMode===id?'active':''}" data-action="exam-mode" data-value="${id}" aria-pressed="${examMode===id}">${icon(ic)}<h3>${name}</h3><p>${copy}</p></button>`).join('')}</div><div class="form-row"><div class="form-field"><label for="exam-chapter">출제 범위</label><select id="exam-chapter" class="input" data-setting="exam-chapter">${opts([['all','1~4장 전체'],...data.map(ch=>[ch.chapter,`${ch.chapter}장 ${ch.title}`])],examChapter)}</select></div><div class="form-field"><label for="exam-minutes">연습 시간</label><select id="exam-minutes" class="input" data-setting="exam-minutes">${opts([['30','30분'],['50','50분'],['60','60분'],['90','90분']],examMinutes)}</select></div></div>${notice('실제 시험 시간·배점이 아니라 연습용 설정입니다. 중간고사 양식은 서술 8점 × 9 + 단답 4점 + 객관 8점 × 3 = 100점으로 연습합니다. 서술형 점수는 채점 요소를 대조한 자기평가입니다.',true)}<ul class="tiny-list"><li>답안은 자동 저장되어 새로고침 후에도 이어 풀 수 있습니다.</li><li>시험 중에는 해설이 보이지 않습니다. 제출 뒤에 전체 풀이를 확인합니다.</li><li>시간이 끝나면 답안 제출과 채점 단계로 자동 전환됩니다.</li><li>범위를 좁히면 가능한 문항 수까지 출제하며, 같은 문항을 중복 출제하지 않습니다.</li></ul><div class="actions section-gap">${btn(`모의고사 시작 ${icon('arrow')}`,'exam-start')}</div></div>${state.examHistory.length?`<section class="surface pad section-gap"><h3>최근 모의고사 기록</h3><div class="table-wrap"><table><thead><tr><th>응시일</th><th>유형</th><th>문항 수</th><th>점수 / 100</th></tr></thead><tbody>${state.examHistory.slice(0,8).map(h=>`<tr><td>${new Date(h.date).toLocaleDateString('ko-KR')}</td><td>${h.mode==='mixed'?'중간고사 양식':h.mode==='written'?'서술·단답':'개념 점검'}</td><td>${h.ids.length}</td><td><b>${h.score}</b>${h.mode!=='objective'?' (자기평가 포함)':''}${h.needsReview?' · 개정 전 문항 포함':''}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function examActive(){const ex=state.exam,q=byId.get(ex.ids[ex.index]);const answered=ex.ids.filter(id=>ex.answers[id]!==undefined&&String(ex.answers[id]).trim()!=='').length;return `<div class="exam-top"><div><div class="eyebrow">EXAM IN PROGRESS</div><h1>모의고사 진행 중</h1><p class="note">${ex.index+1} / ${ex.ids.length}문항 · ${answered}문항 작성</p></div><div class="timer" id="timer" role="timer" aria-label="남은 시간">--:--</div></div><div class="two-col"><div><section class="surface pad"><div class="question-head"><span class="pill gray">문제 ${ex.index+1}</span><span class="pill">${q.chapter}장</span><span class="pill gold">${TYPES[q.type]}</span><span class="note">${ex.mode==='mixed'?questionPoints(q,ex.mode)+'점':'동일 배점'}</span></div>${ex.pendingRevisionIds?.includes(q.id)?notice('검수로 발문·정답 또는 채점 기준이 개정됐습니다. 보관된 답안을 다시 확인하고 답을 입력하거나 선택해 주세요.',true):''}<h2 class="question-prompt">${e(q.prompt)}</h2>${questionInput(q,ex.answers[q.id],true)}</section><div class="question-nav">${btn(`${icon('back')} 이전 문항`,'exam-nav',`data-index="${ex.index-1}" ${ex.index===0?'disabled':''}`,'secondary')}${ex.index<ex.ids.length-1?btn(`다음 문항 ${icon('arrow')}`,'exam-nav',`data-index="${ex.index+1}"`):btn('시험 제출','exam-finish')}</div></div><aside class="surface pad sticky"><h3>답안 현황</h3><p class="note" style="margin:10px 0 15px">초록색은 답안을 작성한 문항입니다.</p><div class="question-map">${ex.ids.map((id,i)=>`<button class="map-btn ${ex.answers[id]!==undefined&&String(ex.answers[id]).trim()!==''?'answered':''} ${i===ex.index?'active':''}" data-action="exam-nav" data-index="${i}" aria-label="${i+1}번 문항 ${ex.answers[id]!==undefined?'작성':'미작성'}">${i+1}</button>`).join('')}</div><div class="actions section-gap">${btn('답안 제출 · 채점','exam-finish','','tiny')}</div><p class="note section-gap">다른 화면으로 이동해도 남은 시간은 계속 흐릅니다. 현재 답안은 자동 저장됩니다.</p></aside></div>`;}
function examReview(){const ex=state.exam,done=ex.status==='done',ungraded=ex.ids.filter(id=>ex.grades[id]===undefined);return `${title('EXAM REVIEW',done?'모의고사 결과':'답안을 채점하고 빈틈을 확인하세요',done?'모든 문항의 풀이와 관련 개념을 다시 확인해 보세요.':'선택형·단답형은 자동 비교했습니다. 서술형은 모범답안과 채점 요소를 대조해 직접 평가해 주세요.')}<section class="surface pad"><div class="spread"><div><div class="eyebrow">${done?'FINAL SCORE':'GRADING PROGRESS'}</div>${done?`<div class="score-big">${examScore(ex,byId)}<small> / 100</small></div><p class="note">${ex.mode!=='objective'?'서술형 자기평가 점수가 포함된 연습 결과입니다.':'문항별 동일 배점으로 100점 환산했습니다.'}</p>`:`<h2>${ex.ids.length-ungraded.length} / ${ex.ids.length}문항 채점 완료</h2><p class="note">아직 채점하지 않은 문항 ${ungraded.length}개</p>`}</div><div class="actions">${done?btn('새 모의고사 준비','exam-new','','secondary'):btn('채점 완료 · 결과 저장','exam-save',ungraded.length?'disabled':'')}</div></div></section>${ex.pendingRevisionIds?.length?notice(`검수로 ${ex.pendingRevisionIds.length}개 문항이 개정됐습니다. 이전 답안은 보관했고, 해당 문항의 점수는 새 기준으로 재확인할 때 반영합니다.`,true):''}${ex.ids.map((id,i)=>{const q=byId.get(id),a=ex.answers[id];return `<article class="surface exam-review-item" id="review-${id}"><div class="spread"><div class="flex"><span class="pill gray">${i+1}번</span><span class="pill gold">${TYPES[q.type]}</span><span class="pill">${q.chapter}장</span></div><span class="small ${ex.grades[id]===1?'done-mark':'muted'}">${ex.grades[id]===undefined?'자기평가 대기':Math.round(ex.grades[id]*100)+'%'}</span></div><h3 style="margin-top:15px">${e(q.prompt)}</h3><div class="user-answer"><span class="note">내 답안</span><br>${a===undefined||String(a).trim()===''?'(미작성)':e(typeof a==='number'?(ex.pendingRevisionIds?.includes(id)?`개정 전 ${a+1}번 보기 선택`:q.options[a]?.text):a)}</div>${q.type==='essay'?`<div class="model-answer"><b>모범답안</b>\n${e(q.answer)}</div>${rubricHTML(q,ex.rubrics[id]||[],'exam-rubric',done)}${!done?btn(ex.grades[id]===undefined?'이 문항 점수 반영':'자기평가 다시 반영','exam-grade',`data-id="${id}"`,'secondary tiny'):''}`:`${!q.options.length?`<div class="model-answer"><b>모범답안</b>\n${e(q.answer)}</div>`:''}${q.type==='short'&&!done&&!ex.pendingRevisionIds?.includes(id)&&ex.grades[id]!==1?btn('동일한 뜻 · 정답으로 인정','exam-short',`data-id="${id}"`,'secondary tiny'):''}`}${ex.pendingRevisionIds?.includes(id)&&q.type!=='essay'?`<div class="actions section-gap"><div style="width:100%">${questionInput(q,ex.revisionDrafts?.[id],'revision')}</div>${btn('새 답안으로 채점하기','exam-recheck',`data-id="${id}" ${ex.revisionDrafts?.[id]===undefined||String(ex.revisionDrafts[id]).trim()===''?'disabled':''}`,'secondary tiny')}</div>`:''}<details><summary>정답 근거와 선택지 해설 보기</summary>${allExplanations(q)}</details></article>`;}).join('')}<div class="actions section-gap">${done?btn('새 모의고사 준비','exam-new'):btn('채점 완료 · 결과 저장','exam-save',ungraded.length?'disabled':'')}</div>`;}
function finishExam(auto=false){const ex=state.exam;if(!ex||ex.status!=='active')return;for(const id of ex.ids){const q=byId.get(id),a=ex.answers[id];if(ex.pendingRevisionIds?.includes(id))continue;if(q.type==='essay'){if(a===undefined||String(a).trim()==='')ex.grades[id]=0;}else ex.grades[id]=q.options.length?(a===q.answer?1:0):checkShort(q,a??'')?1:0;}ex.status='review';save();render();if(auto)toast('시간이 종료되어 답안이 제출됐습니다. 채점을 완료해 주세요.');}
function tick(){const ex=state?.exam;if(ex?.status!=='active')return;const ms=ex.deadline-Date.now();if(ms<=0){finishExam(true);return;}const timer=$('#timer');if(timer){const sec=Math.ceil(ms/1000);timer.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;timer.classList.toggle('urgent',sec<300);}}
function cardsPage(){const list=concepts.filter(c=>flash.chapter==='all'||c.chapter===Number(flash.chapter));if(!flash.ids.length||flash.ids.some(id=>!list.some(c=>c.id===id)))flash.ids=list.map(c=>c.id);flash.index=Math.max(0,Math.min(flash.index,flash.ids.length-1));const c=byConcept.get(flash.ids[flash.index]);return `${title('ACTIVE RECALL','떠올리는 순간, 기억이 됩니다.','정의를 보기 전에 핵심 원리를 소리 내어 설명해 보세요. 카드를 누르면 정답을 확인할 수 있습니다.')}<div class="spread"><select class="input" style="width:240px" aria-label="암기카드 장" data-setting="flash-chapter">${opts([['all','전체 개념'],...data.map(ch=>[ch.chapter,`${ch.chapter}장 ${ch.title}`])],flash.chapter)}</select>${btn(`${icon('refresh')} 섞기`,'flash-shuffle','','secondary tiny')}</div><div class="flashcard"><div class="flash-progress">CARD ${flash.index+1} / ${flash.ids.length} · ${c.chapter}장</div><button class="flash-face" data-action="flash-flip" aria-label="${flash.flipped?'개념 이름 보기':'정의와 핵심 내용 보기'}"><span class="pill">${flash.flipped?'핵심 정의':'이 개념을 설명해 보세요'}</span>${flash.flipped?`<h2 style="font-size:16px">${e(c.title)}</h2><div class="answer">${e(c.summary)}</div><p class="note section-gap">${e(c.pitfalls?.[0]||c.details[0])}</p>`:`<h2>${e(c.title)}</h2>`}<span class="hint">카드를 누르면 ${flash.flipped?'앞면':'뒷면'}이 보입니다.</span></button><div class="flash-actions">${btn('이전','flash-nav',`data-dir="-1" ${flash.index===0?'disabled':''}`,'secondary')}${btn('개념 자세히', 'flash-concept','','secondary')}${btn('다음','flash-nav',`data-dir="1" ${flash.index>=flash.ids.length-1?'disabled':''}`)}</div><div class="actions" style="justify-content:center;margin-top:15px">${btn(state.learned.includes(c.id)?'✓ 확인 완료':'설명할 수 있어요 · 확인 완료','learned',`data-id="${c.id}"`,'ghost tiny')}</div></div>`;}
function statsPage(){const s=stats();const weak=concepts.map(c=>({c,p:conceptProgress(c,questions,state)})).filter(x=>x.p.done>0).sort((a,b)=>(a.p.correct/a.p.done)-(b.p.correct/b.p.done));return `${title('LEARNING INSIGHTS','어디가 헷갈리는지, 분명하게.','최근 답안을 기준으로 분석합니다. 서술형 자기평가와 단답형 정답 인정 결과도 포함됩니다.')}${statCards()}<section class="surface pad"><h2>장별 풀이 현황</h2>${data.map(ch=>{const qs=questions.filter(q=>q.chapter===ch.chapter),done=qs.filter(q=>state.attempts[q.id]&&!state.attempts[q.id].needsReview).length;return `<div class="bar-row"><span>${ch.chapter}장 ${e(ch.title)}</span><div class="progress"><i style="width:${done/qs.length*100}%"></i></div><span class="mono muted">${done} / ${qs.length}</span></div>`;}).join('')}</section><section class="surface pad section-gap"><h2>우선 복습할 개념</h2><p class="note" style="margin:9px 0 15px">문제를 풀어 본 개념 중 완전 정답 비율이 낮은 순서입니다. 미풀이 문제는 정답률 분모에 포함하지 않습니다.</p>${weak.length?`<div class="table-wrap"><table><thead><tr><th>개념</th><th>풀이</th><th>최근 완전 정답</th><th>복습</th></tr></thead><tbody>${weak.slice(0,25).map(({c,p})=>`<tr><td>${c.chapter}장 · ${e(c.title)}</td><td>${p.done} / ${p.total}</td><td>${Math.round(p.correct/p.done*100)}%</td><td>${btn('개념 문제','concept-practice',`data-id="${c.id}"`,'secondary tiny')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><p>아직 학습 기록이 없습니다. 첫 문제를 풀면 개념별 결과가 표시됩니다.</p>${link('문제 풀기','bank')}</div>`}</section>`;}
function reviewSection(){if(!reviewData?.changes?.length)return '';return `<section class="surface pad prose section-gap" style="margin-bottom:24px"><div class="eyebrow">CONTENT REVIEW · ${e(reviewData.date)}</div><h2 style="margin-top:0">이번 재검수에서 보완한 내용</h2><p>수업자료 ${reviewData.reviewedFiles}개, ${reviewData.reviewedSlides}슬라이드와 기존 문항의 발문·정답·보기 해설·채점 요소를 다시 대조했습니다. 문항 수는 ${reviewData.baselineQuestions}개에서 <b>${reviewData.currentQuestions}개</b>로 보완했습니다.</p>${notice('내용이나 채점 기준이 개정된 기존 문항은 오답노트에 ‘개정 전 답안’으로 보관합니다. 다시 풀기 전까지 현재 득점률에서 제외하며 메모와 북마크는 유지합니다.')}<ul>${reviewData.changes.map(c=>`<li><b>${e(c.title)}</b> — ${e(c.description)}${c.questionIds?.length?`<div class="actions" style="margin-top:7px">${c.questionIds.map(id=>link(`${e(id)} 확인`,`practice/${id}`,'secondary tiny')).join('')}</div>`:''}</li>`).join('')}</ul>${reviewData.references?.length?`<p class="note">교정 근거 · ${reviewData.references.map(r=>`<a href="${e(r.url)}" target="_blank" rel="noopener">${e(r.title)}</a>`).join(' · ')}</p>`:''}<p class="note">표지·목차 등에 대한 출처 연결 수와 실제 세부 항목의 이해를 구분하여 검토했습니다. 표·사례의 중요한 내용은 직접 답을 요구하는 문제로 보완했습니다.</p></section>`;}
function sourcesPage(){return `${title('SOURCE & EXAM ANALYSIS','자료를 읽고, 출제 방식을 분석했습니다.','수업자료 4개가 학습 범위의 기준입니다. 과거 시험지는 질문 형식과 답안 작성 방식의 참고 자료로 사용했습니다.')}${reviewSection()}<section class="surface pad prose"><h2 style="margin-top:0">분석한 수업자료</h2><div class="table-wrap"><table><thead><tr><th>강의자료</th><th>슬라이드</th><th>정리 개념</th><th>연습 문항</th></tr></thead><tbody>${data.map(ch=>`<tr><td><b>${ch.chapter}장 · ${e(ch.title)}</b><br><span class="note">${e(ch.sourceFile)}</span></td><td>${ch.slideCount}</td><td>${ch.concepts.length}</td><td>${ch.questions.length}</td></tr>`).join('')}</tbody></table></div><h2>교수님 시험 양식에서 확인한 특징</h2><p>중간고사 양식: 총 14문항 중 수업 의견 1개를 제외하면 학습 문항은 <b>13개</b>입니다. 서술형 9개, 단답형 1개, 4지선다형 3개로 분류했습니다. 기말고사 양식은 서술형 4개, 단답형 8개입니다.</p>${notice('과거 시험지의 장 번호와 지금 PPT의 장 구성이 다릅니다. 과거 시험지에 나온 암호학·블록체인·데이터베이스 주제를 현재 시험 범위라고 단정하지 않았습니다.',true)}<h3>답안은 이렇게 연습하세요</h3><ol><li>“설명하라”: 용어 정의와 작동 원리를 이어서 작성합니다.</li><li>“비교하라”: 같은 기준으로 공통점과 차이점을 적습니다.</li><li>“대응 방안”: 공격의 원인을 밝히고 그 원인을 막는 방어 원리를 설명합니다.</li><li>“조건을 쓰라”: 항목의 이름과 각각의 의미를 함께 씁니다.</li></ol><h2>출제와 해설 원칙</h2><ul><li>제공된 PPT의 텍스트뿐 아니라 이미지로 들어 있는 표와 사례도 함께 확인했습니다. 표지·목차·학습목표·마무리 15쪽을 제외한 본문 229쪽 모두를 문항의 근거 슬라이드와 연결했습니다.</li><li>문제와 개념마다 근거가 된 PPT 슬라이드 번호를 기록했습니다.</li><li>선택형은 모든 보기의 옳고 그름과 그 보기의 실제 개념을 해설했습니다.</li><li>서술형은 모범답안과 채점 요소를 제공하며, 자기평가 점수임을 표시합니다.</li><li>단답형은 등록된 답안과 동의어를 비교합니다. 같은 의미의 표현은 직접 정답 인정할 수 있습니다.</li><li>원본 강의 파일, 시험지 이미지, 타인의 작성 답안은 공개 사이트에 포함하지 않았습니다.</li></ul><h2>혼동하기 쉬운 자료 표현</h2><ul><li><b>GET과 POST:</b> POST 전송 내용은 보통 HTTP 본문에 실립니다. POST라는 이유만으로 암호화되거나 SQL 삽입에 안전해지는 것은 아닙니다. HTTPS와 입력 처리·권한 검사가 별도로 필요합니다.</li><li><b>OWASP:</b> 제공된 4장의 OWASP Top 10:2025 기준을 따릅니다. 연도가 다른 목록과 순위를 섞지 않습니다.</li><li><b>IDS와 IPS:</b> 탐지와 차단의 기능을 구별합니다. 탐지 시스템이 존재한다는 사실만으로 공격 차단을 보장할 수 없습니다.</li><li><b>TCP·주소·무선 표:</b> 연결 상태 이름, 전체 주소 수와 사용 가능한 호스트 수, 무선 표준과 Wi-Fi 세대 이름을 구분합니다. 오래되거나 부정확한 표기를 일반 원리의 정답으로 고정하지 않았습니다.</li></ul><p class="note">이번 자료를 바탕으로 제작한 연습문제이며 실제 출제나 점수를 보장하는 자료는 아닙니다. 마지막에는 수업 중 강조한 부분과 원본 PPT를 함께 확인하세요.</p><h3>개념 교정 시 참고한 공식 문서</h3><ul><li><a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-9.3.3" target="_blank" rel="noopener">IETF · HTTP Semantics (POST)</a></li><li><a href="https://owasp.org/Top10/2025/" target="_blank" rel="noopener">OWASP Top 10:2025</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc9293.html" target="_blank" rel="noopener">IETF · TCP 표준</a></li><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html" target="_blank" rel="noopener">OWASP · SQL Injection Prevention</a></li></ul></section>`;}
function settingsPage(){return `${title('YOUR STUDY RECORD','학습 기록을 안전하게 보관하세요.','풀이 기록, 북마크, 오답 메모와 시험 답안은 이 기기의 현재 브라우저에 저장됩니다. 다른 기기와 자동 동기화되지는 않습니다.')}<div class="settings-grid"><section class="surface pad"><h3>학습 기록 백업</h3><p>기기를 바꾸거나 브라우저 데이터를 지우기 전에 JSON 파일로 저장하세요.</p>${btn(`${icon('download')} 기록 내보내기`,'export')}</section><section class="surface pad"><h3>백업에서 복원</h3><p>이 학습실에서 내보낸 JSON 파일을 선택합니다. 현재 기록은 복원한 기록으로 교체됩니다.</p><label class="btn secondary" for="import-file">기록 파일 선택</label><input type="file" id="import-file" accept="application/json,.json" style="display:none"></section><section class="surface pad"><h3>화면 모드</h3><p>현재 ${state.theme==='dark'?'다크':'라이트'} 모드를 사용하고 있습니다.</p>${btn(`${icon('moon')} 화면 모드 전환`,'theme','','secondary')}</section><section class="surface pad"><h3>학습 기록 초기화</h3><p>현재 브라우저의 풀이 기록, 오답 메모, 북마크와 시험 기록을 지웁니다. 먼저 백업해 두세요.</p>${btn('모든 학습 기록 초기화','reset-state','','danger')}</section></div>${notice('개념 노트는 인쇄 메뉴에서 PDF로 저장할 수 있습니다. 문제와 해설은 공부에 필요한 부분을 펼친 뒤 인쇄하세요.')}<div class="actions section-gap">${btn(`${icon('print')} 현재 화면 인쇄`,'print','','secondary')}</div>`;}

document.addEventListener('click',ev=>{
 const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,v=el.dataset.value,id=el.dataset.id;
 if(a.startsWith('cram-')){cramAction(a,id,v);return;}
 if(a==='menu'){mobile=!mobile;render();return;}
 if(a==='worksheet-expand-all'||a==='worksheet-collapse-all'){for(const q of worksheetQuestions())worksheetDraft(q).revealed=a==='worksheet-expand-all';save();const y=window.scrollY;render();window.scrollTo({top:y,behavior:'instant'});return;}
 if(a.startsWith('worksheet-')){worksheetAction(a,id,el,v);return;}
 if(a==='theme'){state.theme=state.theme==='dark'?'light':'dark';save();render();return;}
 if(a==='print'){window.print();return;}
 if(a==='bank-mode'){bankMode=v;page=0;filters.status='all';render();return;}
 if(a==='chapter'){filters.chapter=filters.chapter===v?'all':v;filters.concept='all';page=0;render();return;}
 if(a==='reset-filter'){filters={query:'',chapter:'all',type:'all',difficulty:'all',status:'all',concept:'all'};page=0;render();return;}
 if(a==='page'){page+=Number(el.dataset.dir);render();$('.list-meta')?.scrollIntoView({block:'start'});return;}
 if(a==='continue'){const q=questions.find(q=>!state.attempts[q.id]||state.attempts[q.id].needsReview)||questions[0];goPractice(q.id,questions);return;}
 if(a==='random'){const pool=bankMode==='course'?questions:filterQuestions();const list=shuffle(pool).slice(0,20);if(list.length)goPractice(list[0].id,list);else toast('조건에 맞는 문제가 없습니다.');return;}
 if(a==='filtered'){const list=filterQuestions();if(list.length)goPractice(list[0].id,list);return;}
 if(a==='chapter-practice'){routeTo('worksheet/'+v);return;}
 if(a==='chapter-learned'){const ch=data.find(ch=>ch.chapter===Number(v));if(!ch)return;const ids=ch.concepts.map(c=>c.id),complete=ids.every(id=>state.learned.includes(id));state.learned=complete?state.learned.filter(id=>!ids.includes(id)):[...new Set([...state.learned,...ids])];save();const y=window.scrollY;render();window.scrollTo({top:y,behavior:'instant'});toast(complete?`${ch.chapter}장 읽기 완료를 취소했습니다.`:`${ch.chapter}장 읽기 완료를 기록했습니다.`);return;}
 if(a==='concept-practice'){const list=questions.filter(q=>q.conceptId===id);if(list.length)goPractice(list[0].id,list);return;}
 if(a==='open-question'){const q=byId.get(id);if(q)routeTo('worksheet/'+q.chapter+'?question='+id);return;}
 if(a==='practice-nav'){if(practice.revealed&&!practice.graded&&byId.get(routeId)?.type==='essay'){toast('채점 요소를 체크하고 자기평가 점수를 먼저 기록해 주세요.');return;}if(id)goPractice(id);return;}
 if(a==='choice'){practice.choice=Number(v);render();return;}
 if(a==='submit'){
   const q=byId.get(routeId);if(!q)return;
   if(q.options.length&&practice.choice===null||!q.options.length&&!practice.text.trim())return;
   practice.revealed=true;
   if(q.type!=='essay'){practice.score=q.options.length?(practice.choice===q.answer?1:0):checkShort(q,practice.text)?1:0;practice.graded=true;recordAttempt(state,q,q.options.length?practice.choice:practice.text,practice.score);save();}
   render();$('.feedback')?.scrollIntoView({behavior:'smooth',block:'start'});return;
 }
 if(a==='rubric'){const n=Number(el.dataset.index);practice.rubric=el.checked?[...new Set([...practice.rubric,n])]:practice.rubric.filter(x=>x!==n);return;}
 if(a==='grade-essay'){const q=byId.get(routeId);practice.score=practice.rubric.length/(q.rubric?.length||1);practice.graded=true;recordAttempt(state,q,practice.text,practice.score,true);save();render();toast('자기평가 점수를 기록했습니다.');return;}
 if(a==='override-short'){const q=byId.get(routeId);practice.score=1;const attempt=state.attempts[q.id];if(attempt){attempt.correct=true;attempt.score=1;attempt.selfGraded=true;}save();render();return;}
 if(a==='retry'){resetPractice();render();window.scrollTo({top:0,behavior:'smooth'});return;}
 if(a==='bookmark'){state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render();return;}
 if(a==='learned'){state.learned=state.learned.includes(id)?state.learned.filter(x=>x!==id):[...state.learned,id];save();render();return;}
 if(a==='review-tab'){reviewTab=v;render();return;}
 if(a==='review-all'||a==='review-question'){const list=reviewTab==='bookmarked'?questions.filter(q=>state.bookmarks.includes(q.id)):wrong();if(list.length)goPractice(id||list[0].id,list);return;}
 if(a==='exam-mode'){examMode=v;render();return;}
 if(a==='exam-start'){const ids=selectExam(questions,examMode,examChapter);if(!ids.length){toast('이 범위에 출제할 수 있는 문제가 없습니다.');return;}state.exam={ids,answers:{},grades:{},rubrics:{},revisions:Object.fromEntries(ids.map(id=>[id,questionRevision(byId.get(id))])),pendingRevisionIds:[],revisionDrafts:{},index:0,mode:examMode,started:Date.now(),deadline:Date.now()+Number(examMinutes)*60000,status:'active'};save();render();window.scrollTo({top:0});return;}
 if(a==='exam-choice'){const ex=state.exam;ex.answers[ex.ids[ex.index]]=Number(v);acknowledgeRevision(ex,byId.get(ex.ids[ex.index]));save();render();return;}
 if(a==='exam-nav'){const ex=state.exam,n=Number(el.dataset.index);if(n>=0&&n<ex.ids.length){ex.index=n;save();render();window.scrollTo({top:0});}return;}
 if(a==='exam-finish'){const ex=state.exam,missing=ex.ids.filter(id=>ex.answers[id]===undefined||String(ex.answers[id]).trim()==='').length;if(window.confirm(missing?`미작성 ${missing}문항이 있습니다. 현재 답안으로 제출할까요?`:'답안을 제출하고 채점할까요?')){finishExam();window.scrollTo({top:0});}return;}
 if(a==='exam-rubric'){const ex=state.exam,n=Number(el.dataset.index),list=ex.rubrics[id]||[];ex.rubrics[id]=el.checked?[...new Set([...list,n])]:list.filter(x=>x!==n);delete ex.grades[id];save();return;}
 if(a==='exam-grade'){const ex=state.exam,q=byId.get(id);ex.grades[id]=(ex.rubrics[id]?.length||0)/(q.rubric?.length||1);acknowledgeRevision(ex,q);save();const y=window.scrollY;render();window.scrollTo({top:y});toast('문항 점수를 반영했습니다.');return;}
 if(a==='exam-short'){state.exam.grades[id]=1;acknowledgeRevision(state.exam,byId.get(id));save();render();return;}
 if(a==='revision-choice'){const ex=state.exam;ex.revisionDrafts??={};ex.revisionDrafts[id]=Number(v);save();const y=window.scrollY;render();window.scrollTo({top:y});return;}
 if(a==='exam-recheck'){const ex=state.exam,q=byId.get(id),answer=ex.revisionDrafts?.[id];if(answer===undefined||String(answer).trim()==='')return;ex.answers[id]=answer;ex.grades[id]=q.options.length?(answer===q.answer?1:0):checkShort(q,answer??'')?1:0;acknowledgeRevision(ex,q);save();const y=window.scrollY;render();window.scrollTo({top:y});return;}
 if(a==='exam-save'){const ex=state.exam;if(ex.ids.some(id=>ex.grades[id]===undefined))return;for(const id of ex.ids){const q=byId.get(id);recordAttempt(state,q,ex.answers[id]??'',ex.grades[id],q.type==='essay'||q.type==='short');}ex.status='done';state.examHistory.unshift({date:Date.now(),ids:ex.ids,mode:ex.mode,score:examScore(ex,byId),revisions:{...ex.revisions}});state.examHistory=state.examHistory.slice(0,30);save();render();window.scrollTo({top:0});return;}
 if(a==='exam-new'){state.exam=null;save();render();window.scrollTo({top:0});return;}
 if(a==='flash-flip'){flash.flipped=!flash.flipped;render();return;}
 if(a==='flash-nav'){flash.index+=Number(el.dataset.dir);flash.flipped=false;render();return;}
 if(a==='flash-shuffle'){flash.ids=shuffle(concepts.filter(c=>flash.chapter==='all'||c.chapter===Number(flash.chapter)).map(c=>c.id));flash.index=0;flash.flipped=false;render();return;}
 if(a==='flash-concept'){routeTo('concept/'+flash.ids[flash.index]);return;}
 if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`컴퓨터보안-학습기록-${new Date().toLocaleDateString('sv-SE')}.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('학습 기록을 내보냈습니다.');return;}
 if(a==='reset-state'){if(window.confirm('현재 브라우저의 모든 학습 기록을 초기화할까요? 백업하지 않은 기록은 복원할 수 없습니다.')){state=emptyState();save();render();toast('학습 기록을 초기화했습니다.');}return;}
});
let searchTimer;
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.input==='cram-answer'){const q=cramQuestions().find(q=>q.id===el.dataset.id);if(q&&q.type!=='mcq'){state.cram.answers[q.id]=el.value.slice(0,12000);save();}return;}if(el.dataset.input==='worksheet-answer'){const q=byId.get(el.dataset.id);if(!q)return;const d=worksheetDraft(q);if(d.revealed||d.graded)return;d.text=el.value.slice(0,12000);save();const submit=document.querySelector(`[data-action="worksheet-show"][data-id="${q.id}"]`);if(submit)submit.textContent=d.text.trim()?'답안 채점 · 정답·해설 보기':'정답·해설 보기';return;}if(el.dataset.filter==='query'){filters.query=el.value;page=0;clearTimeout(searchTimer);searchTimer=setTimeout(render,160);}if(el.dataset.input==='practice-answer'){practice.text=el.value;const submit=$('[data-action="submit"]');if(submit)submit.disabled=!el.value.trim();}if(el.dataset.input==='exam-answer'){const ex=state.exam;if(ex?.status==='active'){ex.answers[ex.ids[ex.index]]=el.value;acknowledgeRevision(ex,byId.get(ex.ids[ex.index]));save();}}if(el.dataset.input==='revision-answer'){state.exam.revisionDrafts??={};state.exam.revisionDrafts[el.dataset.id]=el.value;save();const submit=document.querySelector(`[data-action="exam-recheck"][data-id="${el.dataset.id}"]`);if(submit)submit.disabled=!el.value.trim();}if(el.dataset.input==='personal-note'){state.notes[el.dataset.id]=el.value;save();}});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.dataset.filter&&el.dataset.filter!=='query'){filters[el.dataset.filter]=el.value;if(el.dataset.filter==='chapter')filters.concept='all';page=0;render();}if(el.dataset.setting==='exam-chapter')examChapter=el.value;if(el.dataset.setting==='exam-minutes')examMinutes=el.value;if(el.dataset.setting==='flash-chapter'){flash={chapter:el.value,index:0,flipped:false,ids:[]};render();}if(el.id==='import-file'&&el.files?.[0]){try{if(el.files[0].size>5000000)throw new Error('5MB 이하의 기록 파일을 선택해 주세요.');const imported=sanitizeState(JSON.parse(await el.files[0].text()),questions,concepts,cramData?.topics||[]);if(window.confirm('현재 학습 기록을 선택한 백업의 기록으로 교체할까요?')){state=imported;save();render();toast('학습 기록을 복원했습니다.');}}catch(err){toast(err.message||'올바른 기록 파일을 선택해 주세요.');}el.value='';}});
window.addEventListener('hashchange',readRoute);
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&mobile){mobile=false;render();$('.mobile-menu')?.focus();return;}if(ev.target.matches('input,textarea,select')||ev.ctrlKey||ev.metaKey||ev.altKey)return;if(route==='practice'&&!practice.revealed){const q=byId.get(routeId);if(q?.options.length&&/^[1-4]$/.test(ev.key)&&Number(ev.key)<=q.options.length){practice.choice=Number(ev.key)-1;render();}if(ev.key==='Enter')$('[data-action="submit"]')?.click();}});
setInterval(tick,1000);

async function init(){try{
 const loaded=await Promise.all([1,2,3,4].map(async n=>{const r=await fetch(`./data/chapter${n}.json?v=20261019-r7`);if(!r.ok)throw new Error(`자료 ${n}장을 불러오지 못했습니다.`);return r.json();}));
 const counts=[0,40,74,74,56];data=loaded.map(ch=>({...ch,slideCount:counts[ch.chapter],sourceFile:({1:'01장_정보 보안의 세계v2.pptx',2:'02장_시스템 보안v2.pptx',3:'03장_네트워크 보안v2.pptx',4:'04장_웹 보안v2.pptx'})[ch.chapter]}));
 try{const reviewResponse=await fetch('./data/review-log.json?v=20261019-r7');if(reviewResponse.ok)reviewData=await reviewResponse.json();}catch{}
 const cramResponse=await fetch('./data/cram.json?v=20261019-r7');if(!cramResponse.ok)throw new Error('벼락치기 자료를 불러오지 못했습니다.');cramData=await cramResponse.json();if(!Array.isArray(cramData.topics)||!cramData.topics.length)throw new Error('벼락치기 자료의 형식을 확인해 주세요.');
 concepts=data.flatMap(ch=>ch.concepts);questions=data.flatMap(ch=>ch.questions).map(q=>{
   if(q.type!=='mcq')return q;
   let seed=[...q.id].reduce((v,c)=>Math.imul(v^c.charCodeAt(0),16777619)>>>0,2166136261);const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
   const order=shuffle(q.options.map((_,i)=>i),rng);return {...q,options:order.map(i=>q.options[i]),answer:order.indexOf(q.answer)};
 });
 byId=new Map(questions.map(q=>[q.id,q]));byConcept=new Map(concepts.map(c=>[c.id,c]));state=emptyState();
 try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)state=sanitizeState(JSON.parse(saved),questions,concepts,cramData?.topics||[]);}catch{toast('저장 기록을 읽지 못했습니다. 백업 파일이 있다면 설정에서 복원해 주세요.');}
 try{const queue=JSON.parse(sessionStorage.getItem('security-practice-queue')||'[]');practiceQueue=[...new Set(queue.filter(id=>byId.has(id)))];}catch{}
 readRoute();
}catch(err){$('#app').innerHTML=`<div class="boot"><h1>학습 자료를 불러오지 못했습니다.</h1><p>${e(err.message)}</p><p>인터넷 연결을 확인한 뒤 새로고침해 주세요.</p><button class="btn" onclick="location.reload()">다시 불러오기</button></div>`;}}
init();
